/*
 * Version script for libext2_com_err.so (OpenHarmony GN build, see BUILD.gn).
 * Exports the com_err / error_table API declared in lib/et/com_err.h
 * and lib/et/error_table.h;
 * everything else is hidden via local: *;. Reference from
 * ohos_shared_library("libext2_com_err"):
 *     version_script = "libext2_com_err.map"
 */
E2FSPROGS_1.0 {
	global:
		com_err*;
		com_right*;
		add_error_table;
		add_to_error_table;
		remove_error_table;
		free_error_table;
		init_error_table;
		initialize_error_table_r;
		error_table_name;
		error_message;
		set_com_err_hook;
		reset_com_err_hook;
		set_com_err_gettext;
		et_list_lock;
		et_list_unlock;

	local:
		*;
};
